package com.cinenest.booking.internal;
import java.time.*;import java.util.*;
import org.junit.jupiter.api.Test;import org.junit.jupiter.params.ParameterizedTest;import org.junit.jupiter.params.provider.ValueSource;
import org.springframework.util.LinkedMultiValueMap;
import static org.assertj.core.api.Assertions.*;
class StaffBookingReadRulesTest {
 private final UUID venue=UUID.randomUUID();
 private LinkedMultiValueMap<String,String> params(String from,String to){var p=new LinkedMultiValueMap<String,String>();p.add("from",from);p.add("to",to);return p;}
 @Test void approvedElapsed31DayBoundAndOffsetEquivalence(){var q=StaffBookingReadRules.query(venue,params("2026-10-01T05:30:00+05:30","2026-11-01T00:00:00Z"),false);assertThat(Duration.between(q.from(),q.to())).isEqualTo(Duration.ofDays(31));assertThatThrownBy(()->StaffBookingReadRules.query(venue,params("2026-10-01T00:00:00Z","2026-11-01T00:00:00.000000001Z"),false)).isInstanceOf(StaffBookingReadRules.Failure.class);}
 @Test void paginationUsesExistingCustomerBoundsAndNoImplicitDateRange(){var q=StaffBookingReadRules.query(venue,new LinkedMultiValueMap<>(),false);assertThat(q.page()).isZero();assertThat(q.size()).isEqualTo(10);assertThat(q.from()).isNull();assertThat(q.to()).isNull();}
 @ParameterizedTest @ValueSource(strings={"2026-10-01T00:00:00","2026-10-01T00:00:00+19:00","invalid","0000-10-01T00:00:00Z"}) void invalidOrNonOffsetDatesRejected(String from){assertThatThrownBy(()->StaffBookingReadRules.query(venue,params(from,"2026-10-02T00:00:00Z"),false)).isInstanceOf(StaffBookingReadRules.Failure.class);}
 @Test void emptyReversedAndUnpairedDatesRejected(){for(var p:List.of(params("2026-10-02T00:00:00Z","2026-10-01T00:00:00Z"),params("2026-10-01T00:00:00Z","2026-10-01T00:00:00Z"),params("",""))){assertThatThrownBy(()->StaffBookingReadRules.query(venue,p,false)).isInstanceOf(StaffBookingReadRules.Failure.class);}var p=new LinkedMultiValueMap<String,String>();p.add("from","2026-10-01T00:00:00Z");assertThatThrownBy(()->StaffBookingReadRules.query(venue,p,false)).isInstanceOf(StaffBookingReadRules.Failure.class);}
 @Test void duplicateUnknownAndDetailFiltersRejected(){var p=params("2026-10-01T00:00:00Z","2026-10-02T00:00:00Z");p.add("from","2026-10-01T00:00:00Z");assertThatThrownBy(()->StaffBookingReadRules.query(venue,p,false)).isInstanceOf(StaffBookingReadRules.Failure.class);p.clear();p.add("sort","owner");assertThatThrownBy(()->StaffBookingReadRules.query(venue,p,false)).isInstanceOf(StaffBookingReadRules.Failure.class);p.clear();p.add("page","0");assertThatThrownBy(()->StaffBookingReadRules.query(venue,p,true)).isInstanceOf(StaffBookingReadRules.Failure.class);}
 @Test void referenceIsAnExactOpaqueUuid(){assertThat(StaffBookingReadRules.id(venue.toString())).isEqualTo(venue);for(String id:List.of("1-1-1-1-1",venue+"\n","","../private"))assertThatThrownBy(()->StaffBookingReadRules.id(id)).isInstanceOf(StaffBookingReadRules.Failure.class);}
 @Test void databaseBoundaryCeilingPreservesNanosecondPredicate(){Instant t=Instant.parse("2026-10-01T00:00:00.000000001Z");assertThat(StaffBookingReadRules.databaseBoundary(t)).isEqualTo(Instant.parse("2026-10-01T00:00:00.000001Z"));assertThat(StaffBookingReadRules.databaseBoundary(t.minusNanos(1))).isEqualTo(t.minusNanos(1));}
 @Test void oversizedAndNegativePaginationRejected(){for(String value:List.of("0","26","-1","999999999999999999","01")){var p=new LinkedMultiValueMap<String,String>();p.add("size",value);assertThatThrownBy(()->StaffBookingReadRules.query(venue,p,false)).isInstanceOf(StaffBookingReadRules.Failure.class);}var p=new LinkedMultiValueMap<String,String>();p.add("page","10001");assertThatThrownBy(()->StaffBookingReadRules.query(venue,p,false)).isInstanceOf(StaffBookingReadRules.Failure.class);}
}
